def can_coerce_to(type_tags, target_type): return reduce(lambda type_tag, result: (result and (type_tag == target_type or not is_none(get_coercion(type_tag, target_type)))), True, type_tags)
def find_coerced_type(type_tags): return (None if is_none(type_tags) else head(type_tags) if can_coerce_to(type_tags, head(type_tags)) else find_coerced_type(tail(type_tags)))
def coerce_all(args, target_type): return map(lambda arg: arg if type_tag(arg) == target_type else get_coercion(type_tag(arg), target_type)(arg), args)
def apply_generic(op, args): type_tags = map(type_tag, args) fun = get(op, type_tags) if not is_none(fun): return apply(fun, map(contents, args)) else: target_type = find_coerced_type(type_tags) # proceed only if coercion makes progress; if the arguments are # already all of the target type, there is no applicable method if (not is_none(target_type) and not reduce(lambda t, acc: acc and t == target_type, True, type_tags)): return apply_generic(op, coerce_all(args, target_type)) else: return error("no method for these types", llist(op, type_tags))
Ситуація, де цей підхід не спрацьовує, — це коли є три типи, A, B, C, де A можна звести до B, а C можна звести до B, і є зареєстрована операція для (A, B, B). Обчислення операції для (A, B, C) спробує лише (A, B, C) і (B, B, B), тоді як можна просто звести C до B і скористатися зареєстрованою операцією для (A, B, B).
Умова, що аргументи ще не всі мають тип target_type потрібна, щоб гарантувати завершення: без неї зведення аргументів, які вже мають цільовий тип, залишило б теги типів без змін і викликало б apply_generic знову з тими самими аргументами, зациклюючись назавжди щоразу, коли для такої комбінації типів не зареєстровано методу.
